def warp_perspective(img, H):
    out = new_image(img.w, img.h)
    Hinv = inverse_3x3(H)  # 역변환으로 출력→입력
    for y in range(img.h):
        for x in range(img.w):
            # 동차좌표 역투영
            sx, sy, sw = matvec(Hinv, [x, y, 1])
            u, v = sx / sw, sy / sw  # 정규화
            if 0 <= u < img.w and 0 <= v < img.h:
                out[y][x] = bilinear(img, u, v)
    return out

petri-net.pseudocode:
def enabled(t, m, pre):  # 모든 입력 플레이스에 토큰 충분?
    return all(m.get(p, 0) >= n for p, n in pre[t].items())

def fire(t, m, pre, post):  # 입력 토큰 소비 → 출력 생성
    m2 = dict(m)
    for p, n in pre[t].items():
        m2[p] -= n
    for p, n in post[t].items():
        m2[p] = m2.get(p, 0) + n
    return m2

def explore(m0, pre, post):  # 도달 가능 마킹 BFS
    key = lambda m: frozenset(x for x in m.items() if x[1])
    seen, queue, dead = {key(m0)}, [m0], []
    while queue:
        m = queue.pop(0)
        ready = [t for t in pre if enabled(t, m, pre)]
        if not ready:
            dead.append(m)  # 교착(또는 정상 종료) 마킹
        for t in ready:
            m2 = fire(t, m, pre, post)
            if key(m2) not in seen:
                seen.add(key(m2))
                queue.append(m2)
    return seen, dead  # 비유계 망은 종료 안 됨
